-- amendLoan: Amend a loan's note, starting its renewals again
-- Changes exactly 1 Loan record of table loans: sets note, renewals to 0, by id, where status != "returned".
-- Dry run: mariadb --init-command="SET @id = '...', [@note = '...'], @last_modified_by_user_id = '...', @last_modified_by_user_nameid = '...'" <database> < amend-loan.sql
-- Apply: the same with @apply = true in the SET. Without it every check runs against the data and the change is rolled back.
-- A variable in brackets may be left out: its column is set to NULL.
SET SESSION sql_mode = CONCAT_WS(',', NULLIF(REPLACE(@@SESSION.sql_mode, 'NO_BACKSLASH_ESCAPES', ''), ''), 'STRICT_ALL_TABLES');
DELIMITER //
BEGIN NOT ATOMIC
  DECLARE found BIGINT;
  DECLARE changed BIGINT;
  DECLARE refusal TEXT;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  -- The variables: each is set, and its text is a value of its column.
  IF @apply IS NOT NULL AND NOT LOWER(@apply) IN ('true', 'false', '1', '0') THEN
    SET refusal = CONCAT('amend-loan.sql: the variable @apply is ', QUOTE(@apply), ', which is not true or false; nothing was read');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
  END IF;
  IF @id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'amend-loan.sql: the variable @id is not set; give it as SET @id = ''<Loan.id>'' (CHAR(36)) in --init-command';
  END IF;
  IF @id IS NOT NULL AND NOT (@id REGEXP '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}\\z') THEN
    SET refusal = CONCAT('amend-loan.sql: the variable @id is ', QUOTE(@id), ', which is not a uuid for Loan.id (CHAR(36)); nothing was read');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
  END IF;
  IF @last_modified_by_user_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'amend-loan.sql: the variable @last_modified_by_user_id is not set; give it as SET @last_modified_by_user_id = ''<last_modified_by_user_id>'' (VARCHAR(255)) in --init-command';
  END IF;
  IF @last_modified_by_user_nameid IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'amend-loan.sql: the variable @last_modified_by_user_nameid is not set; give it as SET @last_modified_by_user_nameid = ''<last_modified_by_user_nameid>'' (VARCHAR(255)) in --init-command';
  END IF;
  START TRANSACTION;
  script: BEGIN
    -- 1. Already applied: the record already holds what the change writes.
    IF EXISTS (SELECT 1 FROM loans WHERE id = CAST(@id AS CHAR) AND note <=> CONVERT(@note USING utf8mb4) COLLATE utf8mb4_nopad_bin AND renewals <=> 0) THEN
      SELECT CONCAT('operation amendLoan: the Loan with id ', @id, ' already holds the values written; nothing to change') AS message;
      ROLLBACK;
      LEAVE script;
    END IF;
    -- 2. Precondition: exactly 1 Loan record to change, locked until the end.
    SELECT COUNT(*) INTO found FROM loans
      WHERE id = CAST(@id AS CHAR)
        AND (status <> 'returned')
        AND is_deleted = false
      FOR UPDATE;
    IF found <> 1 THEN
      SET refusal = CONCAT('operation amendLoan: ', found, ' Loan records hold id ', @id, ', status != "returned", not deleted, and the change expects exactly 1; nothing was changed');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
    END IF;
    -- 3. The change, under the same condition.
    UPDATE loans
      SET note = CAST(@note AS CHAR),
        renewals = 0,
        last_modified_at = DATE_FORMAT(UTC_TIMESTAMP(6), '%Y-%m-%dT%H:%i:%s.%f000Z'),
        last_modified_by_user_id = CAST(@last_modified_by_user_id AS CHAR),
        last_modified_by_user_nameid = CAST(@last_modified_by_user_nameid AS CHAR)
      WHERE id = CAST(@id AS CHAR)
        AND (status <> 'returned')
        AND is_deleted = false;
    SET changed = ROW_COUNT();
    -- 4. Postcondition: the exact count, and the record holds what was written.
    IF changed <> 1 THEN
      SET refusal = CONCAT('operation amendLoan: the change wrote ', changed, ' Loan records, and exactly 1 was expected; another writer may have changed them after they were counted; nothing was changed');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM loans WHERE id = CAST(@id AS CHAR) AND note <=> CONVERT(@note USING utf8mb4) COLLATE utf8mb4_nopad_bin AND renewals <=> 0) THEN
      SET refusal = CONCAT('operation amendLoan: after the change the Loan with id ', @id, ' does not hold the values written; nothing was changed');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = refusal;
    END IF;
    -- 5. Dry run unless apply is true.
    IF LOWER(@apply) IN ('true', '1') THEN
      SELECT 'operation amendLoan: 1 Loan record changed; committing' AS message;
      COMMIT;
    ELSE
      SELECT 'operation amendLoan: dry run: 1 Loan record would change, and every check passed; rolling back. Run it again with @apply = true to make the change' AS message;
      ROLLBACK;
    END IF;
  END script;
END//
DELIMITER ;
